def B(text, cite, kind=None):
    item = {"text": text, "cite": cite}
    if kind: item["kind"] = kind
    return item

def E(text, cite, evidence, limit):
    return {"kind": "analysis", "text": text, "cite": cite, "evidence": evidence, "limit": limit}

def F(entries, note, follow):
    status = "complete" if len(entries) >= 5 else ("partial" if entries else "needs-research")
    return {"status": status, "coverage": {"completed": len(entries), "required": 5},
            "sourceCoverageNote": note, "followUp": follow, "entries": entries}

