# حذفِ مدخل‌های هم‌پوشانِ ابن‌عاشور برای پاسداشتِ سقفِ سهمِ یک اثرِ معاصر (۶۰٪)؛
# شاخص‌ها بر اساسِ ترتیبِ مدخل‌ها در همین فایل‌اند و فقط مدخل‌هایی حذف شده‌اند که
# همتای آن‌ها از منبعِ دیگری در همان رکورد هست.
TRIM = {
 "1:3": [("notes", 3), ("context", 2), ("classical", 3), ("critical", 2), ("research", 3),
         ("linguistics", 1), ("linguistics", 0), ("guidanceDiscourse", 1), ("criticalDiscourseAnalysis", 0),
         ("modern", 0), ("critical", 0), ("balaghaNazm", 2)],
 "1:4": [("context", 0), ("modern", 1), ("critical", 2), ("research", 3),
         ("linguistics", 2), ("philosophicalFoundations", 0), ("guidanceDiscourse", 0),
         ("shubuhat", 1), ("historicalContext", 1), ("balaghaNazm", 1)],
 "1:5": [("classical", 3), ("critical", 2), ("research", 0), ("balaghaNazm", 0), ("balaghaNazm", 2),
         ("linguistics", 2), ("philosophicalFoundations", 2), ("guidanceDiscourse", 2)],
 "1:6": [("notes", 3), ("context", 2), ("modern", 1), ("critical", 1),
         ("philosophicalFoundations", 1), ("philosophicalFoundations", 2),
         ("guidanceDiscourse", 2), ("balaghaNazm", 1), ("criticalDiscourseAnalysis", 0)],
 "1:7": [("modern", 1), ("critical", 2), ("research", 3), ("linguistics", 2),
         ("philosophicalFoundations", 1), ("balaghaNazm", 1)],
}

def build(vid, spec):
    rec = {"tier": "core", "sourcePolicyVersion": 2,
           "title": spec["title"],
           "reviewStatus": f"پیش‌نویسِ منبع‌محور؛ «{spec['arab']}»؛ {spec['trans']}",
           "coverageNote": "این رکورد در سطحِ core است: شش فیلدِ پایه هر یک دست‌کم چهار مدخل دارند و فیلدهای افزوده فقط جایی آمده‌اند که برای همان آیه منبعِ مقابله‌شده بوده است؛ فیلدِ غایب در رابط کاربری «نیازمند پژوهش» نشان داده می‌شود.",
           "fieldCoverageStatus": "شش فیلدِ پایه دست‌کم چهارمدخلی‌اند و فیلدهای افزوده با محتوای مقابله‌شدهٔ همان آیه پر شده‌اند؛ هر جا منبعِ مقابله‌شده داده‌ای نداشته، همان کمبود صادقانه ثبت شده است."}
    for f in ("notes", "context", "classical", "modern", "critical", "research"):
        rec[f] = list(spec[f])
    if vid in SAADI_MODERN:
        rec["modern"].append(SAADI_MODERN[vid])
    if vid in SPERL_CRIT:
        rec["critical"].append(SPERL_CRIT[vid])
    if vid in MIZ_BASE:
        rec["modern"].append(MIZ_BASE[vid])
    rec["extendedFields"] = spec["extended"]
    for fid, entry in SAADI_EXT.get(vid, []):
        fld = rec["extendedFields"][fid]
        fld["entries"].append(entry)
        fld["coverage"] = {"completed": len(fld["entries"]), "required": 5}
        fld["status"] = "complete" if len(fld["entries"]) >= 5 else "partial"
    for fid, idx in sorted(TRIM.get(vid, []), reverse=True):
        if fid in ("notes", "context", "classical", "modern", "critical", "research"):
            rec[fid].pop(idx)
        else:
            fld = rec["extendedFields"][fid]
            fld["entries"].pop(idx)
            fld["coverage"] = {"completed": len(fld["entries"]), "required": 5}
            fld["status"] = "complete" if len(fld["entries"]) >= 5 else ("partial" if fld["entries"] else "needs-research")
    for e in rec["extendedFields"].get("bibleComparison", {}).get("entries", []):
        if "Bible-KJV" not in e["cite"]:
            _t = e["text"]
            _book = ("Matthew" if ("Matthew" in _t or "متی" in _t or "دعای ربانی" in _t)
                     else "Genesis" if "Genesis" in _t
                     else "Psalms" if ("Psalm" in _t or "مزمور" in _t)
                     else "Deuteronomy" if "Deuteronomy" in _t else None)
            if _book:
                e["cite"] += f"؛ متنِ عهدینی: KJV؛ Arul John, Bible-KJV، commit a9aa4e55afbb3e095f57e4b14cd1f22c5ee8d7c9، {_book}.json"
    counts = {w: 0 for w, _ in ROLES}
    def scan(items):
        for it in items:
            c = it.get("cite", "")
            for w, _ in ROLES:
                if MARK[w] in c: counts[w] += 1
    for f in ("notes", "context", "classical", "modern", "critical", "research"):
        scan(rec[f])
    for fld in rec["extendedFields"].values():
        scan(fld["entries"])
    rec["sourceMix"] = [{"work": w, "role": r, "entries": counts[w]} for w, r in ROLES if counts[w] > 0]
    rec["requiresDiverseSources"] = True
    return rec

def main():
    data = json.loads(DATA_PATH.read_text(encoding="utf-8"))
    verses = data["verses"]
    for vid, spec in VERSES.items():
        verses[vid] = build(vid, spec)
    # ۱:۱ تا ۱:۷ در ابتدای نقشهٔ آیات
    ordered = {vid: verses[vid] for vid in VERSES}
    for k, v in verses.items():
        if k not in ordered: ordered[k] = v
    data["verses"] = ordered
    for s_item in data.get("scope") or []:
        if s_item.get("range") == "9:1–129" and "۵۰۲۶ رکورد" in s_item.get("status", ""):
            s_item["status"] = s_item["status"].replace("۵۰۲۶ رکورد", "۵۰۳۳ رکورد")
    scope = data.get("scope") or []
    if not any(s.get("range") == "1:1–7" for s in scope):
        scope.insert(0, {"range": "1:1–7", "status": "فاتحه ۱:۱–۷ از اولین آیهٔ قرآن با مدلِ آیه‌محور ساخته شد: شش فیلدِ پایهٔ چهارمدخلی و فیلدهای افزوده فقط با مادهٔ مقابله‌شدهٔ همان آیه از طبری و قرطبی و ابن‌عاشور و المیزان (ج۱) و پژوهش‌های دوپوشه و اسپرل؛ قرائتی و تفسیر نور استفاده نشده و المیسّر به کار نرفته و فیلدِ بی‌ماده غایب و نیازمند پژوهش مانده است."})
        data["scope"] = scope
    DATA_PATH.write_text(json.dumps(data, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
    print("done", len(VERSES))

if __name__ == "__main__":
    main()
